<?php
declare(strict_types=1);
require_once __DIR__ . '/../config/bootstrap.php';
$admin=require_admin($pdo);
$pageTitle='Inseratsübersicht';
if (!in_array($_SERVER['REQUEST_METHOD'], ['GET','HEAD'], true) || isset($_GET['action']) || isset($_GET['delete_id'])) abort_request(405,'Diese Übersicht ist ausschließlich lesbar.');
$states=['draft'=>'Entwurf','active'=>'Aktiv','paused'=>'Pausiert','ended'=>'Beendet','sold'=>'Verkauft','archived'=>'Archiviert','review'=>'Prüfung notwendig'];
$status=$_GET['status']??'';
if (!is_string($status)||($status!==''&&!isset($states[$status]))) abort_request(422,'Ungültiger Statusfilter.');
$detail=null;$events=[];
if (isset($_GET['id'])) {
 $id=filter_var($_GET['id'],FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);
 if ($id===false) abort_request(422,'Ungültige Inseratsnummer.');
 $q=$pdo->prepare('SELECT l.*,u.username,c.name AS category_name FROM market_listings l JOIN users u ON u.id=l.seller_id JOIN market_categories c ON c.id=l.category_id WHERE l.id=?');$q->execute([$id]);$detail=$q->fetch();
 if (!$detail) abort_request(404,'Inserat nicht gefunden.');
 $q=$pdo->prepare('SELECT event_type,amount_cents,created_at FROM market_bids WHERE listing_id=? ORDER BY id DESC LIMIT 40');$q->execute([$id]);$events=$q->fetchAll();
}
$page=filter_var($_GET['page']??'1',FILTER_VALIDATE_INT,['options'=>['min_range'=>1,'max_range'=>100000]])?:1;
$where=$status===''?'1=1':'l.status=?';$parameters=$status===''?[]:[$status];
$q=$pdo->prepare('SELECT COUNT(*) FROM market_listings l WHERE '.$where);$q->execute($parameters);$total=(int)$q->fetchColumn();$page=min($page,max(1,(int)ceil($total/30)));
$q=$pdo->prepare('SELECT l.id,l.title,l.type,l.status,l.price_cents,l.current_bid_cents,l.created_at,u.username,c.name AS category_name FROM market_listings l JOIN users u ON u.id=l.seller_id JOIN market_categories c ON c.id=l.category_id WHERE '.$where.' ORDER BY l.id DESC LIMIT 30 OFFSET '.(($page-1)*30));$q->execute($parameters);$items=$q->fetchAll();
include __DIR__.'/../includes/header.php';
?>
<main class="container admin-page"><div class="page-heading"><div><p class="eyebrow">Überblick ohne verdeckte Eingriffe</p><h1>Angebote & Auktionen.</h1><p>Nur allgemeine Marktplatzangebote. Historische spezialisierte Angebote sind ausgeschlossen.</p></div></div><div class="admin-layout"><?php include __DIR__.'/../includes/admin-nav.php'; ?><div class="admin-content">
<?php if ($detail): ?><section class="panel"><p class="eyebrow">Inserat #<?= (int)$detail['id'] ?></p><h2><?= h($detail['title']) ?></h2><p><span class="status"><?= h($states[$detail['status']]??$detail['status']) ?></span> · <?= h($detail['username']) ?> · <?= h($detail['category_name']) ?></p><p><?= h($detail['description']) ?></p><?php if ($detail['status']==='review'): ?><div class="notice error"><h3>Abschlusskonflikt</h3><p>Die automatische Verarbeitung hat dieses Angebot zur Prüfung zurückgestellt. Gebote und Maximalgebote wurden nicht gelöscht oder nachträglich korrigiert. Diese Übersicht erlaubt keine unkontrollierte Gewinneränderung. Prüfe die Auktionsdaten mit einem dokumentierten Korrekturprozess.</p></div><?php endif; ?><h3>Letzte Auktionsereignisse</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>Ereignis</th><th>Öffentlicher Betrag</th><th>Zeitpunkt (UTC)</th></tr></thead><tbody><?php foreach ($events as $event): ?><tr><td><?= h($event['event_type']) ?></td><td><?= $event['amount_cents']===null?'—':h(money_eur((int)$event['amount_cents'])) ?></td><td><?= h($event['created_at']) ?></td></tr><?php endforeach; ?><?php if ($events===[]): ?><tr><td colspan="3">Noch keine Auktionsereignisse.</td></tr><?php endif; ?></tbody></table></div><p class="muted">Private Maximalgebote werden hier nicht angezeigt.</p></section><?php endif; ?>
<section class="panel"><form method="get" action="/admin/listings.php" class="toolbar"><div class="field"><label for="listing-status">Status</label><select id="listing-status" name="status"><option value="">Alle Status</option><?php foreach ($states as $value=>$label): ?><option value="<?= h($value) ?>"<?= $status===$value?' selected':'' ?>><?= h($label) ?></option><?php endforeach; ?></select></div><button class="button secondary" type="submit">Filtern</button></form><div class="table-wrap"><table class="data-table"><thead><tr><th>Angebot</th><th>Verkäufer</th><th>Typ & Status</th><th>Preis</th><th>Prüfung</th></tr></thead><tbody><?php foreach ($items as $item): ?><tr><td><strong><?= h($item['title']) ?></strong><br><span class="muted"><?= h($item['category_name']) ?> · #<?= (int)$item['id'] ?></span></td><td><?= h($item['username']) ?></td><td><?= $item['type']==='auction'?'Auktion':'Festpreis' ?><br><span class="status"><?= h($states[$item['status']]??$item['status']) ?></span></td><td><?= h(money_eur((int)($item['current_bid_cents']??$item['price_cents']))) ?></td><td><a href="/admin/listings.php?id=<?= (int)$item['id'] ?>">Details ↗</a></td></tr><?php endforeach; ?><?php if ($items===[]): ?><tr><td colspan="5">Keine Angebote für diesen Filter.</td></tr><?php endif; ?></tbody></table></div></section><nav class="pagination" aria-label="Inseratsseiten"><?php if ($page>1): ?><a href="?<?= h(http_build_query(['status'=>$status,'page'=>$page-1])) ?>">← Zurück</a><?php endif; ?><span>Seite <?= $page ?> von <?= max(1,(int)ceil($total/30)) ?></span><?php if ($page*30<$total): ?><a href="?<?= h(http_build_query(['status'=>$status,'page'=>$page+1])) ?>">Weiter →</a><?php endif; ?></nav></div></div></main>
<?php include __DIR__.'/../includes/footer.php'; ?>
